import {
  WebSocketGateway,
  WebSocketServer,
  OnGatewayInit,
  OnGatewayConnection,
  OnGatewayDisconnect,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { interval, Subscription } from 'rxjs';
import { CryptoService } from './crypto.service';

@WebSocketGateway({
  cors: {
    origin: '*', // Cho phép Frontend React kết nối WebSocket
  },
})
export class CryptoGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private priceUpdateSubscription: Subscription;

  constructor(private readonly cryptoService: CryptoService) {}

  afterInit(server: Server) {
    console.log('⚡ WebSocket Gateway đã khởi tạo thành công!');
    this.startRealtimePriceUpdates();
  }

  handleConnection(client: Socket) {
    console.log(`🔌 Client kết nối WebSocket: ${client.id}`);
  }

  handleDisconnect(client: Socket) {
    console.log(`❌ Client ngắt kết nối WebSocket: ${client.id}`);
  }

  // Sử dụng RxJS Observable interval để đẩy dữ liệu mỗi 3 giây
  private startRealtimePriceUpdates() {
    this.priceUpdateSubscription = interval(3000).subscribe(async () => {
      const coins = await this.cryptoService.getTopCoins();

      // Giả lập biến động giá nhẹ (+/- 0.5%) để hiển thị hiệu ứng xanh/đỏ ở Frontend
      const updatedCoins = coins.map((coin) => {
        const randomChange = (Math.random() - 0.48) * 2; // Tỉ lệ tăng/giảm nhẹ
        const newPrice = coin.price * (1 + randomChange / 100);
        return {
          ...coin,
          price: Number(newPrice.toFixed(2)),
          priceChange24h: Number((coin.priceChange24h + randomChange / 5).toFixed(2)),
          isUp: randomChange >= 0, // Đánh dấu tăng (xanh) hay giảm (đỏ)
        };
      });

      // Bắn event 'price_updates' xuống toàn bộ client đang mở web
      this.server.emit('price_updates', updatedCoins);
    });
  }
}
